        /// <item><description><see cref="CSDL.Props.WindowUikitMetalViewTagNumber">WindowUikitMetalViewTagNumber</see>: the NSInteger tag associated with metal views on the window</description></item>
        /// <item><description><see cref="CSDL.Props.WindowUikitOpenglFramebufferNumber">WindowUikitOpenglFramebufferNumber</see>: the OpenGL view's framebuffer object. It must be bound when rendering to the screen using OpenGL.</description></item>
        /// <item><description><see cref="CSDL.Props.WindowUikitOpenglRenderbufferNumber">WindowUikitOpenglRenderbufferNumber</see>: the OpenGL view's renderbuffer object. It must be bound when <see cref="CSDL.Video.Window.SwapOpenGL">SwapOpenGL</see> is called.</description></item>
        /// <item><description><see cref="CSDL.Props.WindowUikitOpenglResolveFramebufferNumber">WindowUikitOpenglResolveFramebufferNumber</see>: the OpenGL view's resolve framebuffer, when MSAA is used.</description></item>
        /// </list>
        /// <para>On KMS/DRM:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.WindowKMSDRMDeviceIndexNumber">WindowKMSDRMDeviceIndexNumber</see>: the device index associated with the window (e.g. the X in /dev/dri/cardX)</description></item>
        /// <item><description><see cref="CSDL.Props.WindowKMSDRMDrmFdNumber">WindowKMSDRMDrmFdNumber</see>: the DRM FD associated with the window</description></item>
        /// <item><description><see cref="CSDL.Props.WindowKMSDRMGbmDevicePointer">WindowKMSDRMGbmDevicePointer</see>: the GBM device associated with the window</description></item>
        /// </list>
        /// <para>On macOS:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.WindowCocoaWindowPointer">WindowCocoaWindowPointer</see>: the <c>(__unsafe_unretained)</c> NSWindow associated with the window</description></item>
