        /// </list>
        /// <para>On Vivante:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.WindowVivanteDisplayPointer">WindowVivanteDisplayPointer</see>: the EGLNativeDisplayType associated with the window</description></item>
        /// <item><description><see cref="CSDL.Props.WindowVivanteWindowPointer">WindowVivanteWindowPointer</see>: the EGLNativeWindowType associated with the window</description></item>
        /// <item><description><see cref="CSDL.Props.WindowVivanteSurfacePointer">WindowVivanteSurfacePointer</see>: the EGLSurface associated with the window</description></item>
        /// </list>
