        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.WindowWaylandDisplayPointer">WindowWaylandDisplayPointer</see>: the wl_display associated with the window</description></item>
        /// <item><description><see cref="CSDL.Props.WindowWaylandSurfacePointer">WindowWaylandSurfacePointer</see>: the wl_surface associated with the window</description></item>
        /// <item><description><see cref="CSDL.Props.WindowWaylandViewportPointer">WindowWaylandViewportPointer</see>: the wp_viewport associated with the window</description></item>
        /// <item><description><see cref="CSDL.Props.WindowWaylandEGLWindowPointer">WindowWaylandEGLWindowPointer</see>: the wl_egl_window associated with the window</description></item>
        /// <item><description><see cref="CSDL.Props.WindowWaylandWindowIDString">WindowWaylandWindowIDString</see>: the window identification string, initially set with <see cref="CSDL.Props.WindowCreateWaylandWindowIDString">WindowCreateWaylandWindowIDString</see>, and used as an identifier for session management. Setting this to null or an empty string ("") before hiding or destroying the window will cause any session information associated with the window to be removed</description></item>
        /// <item><description><see cref="CSDL.Props.WindowWaylandXdgSurfacePointer">WindowWaylandXdgSurfacePointer</see>: the xdg_surface associated with the window</description></item>
        /// <item><description><see cref="CSDL.Props.WindowWaylandXdgToplevelPointer">WindowWaylandXdgToplevelPointer</see>: the xdg_toplevel role associated with the window</description></item>
        /// <item><description>'<see cref="CSDL.Props.WindowWaylandXdgToplevelExportHandleString">WindowWaylandXdgToplevelExportHandleString</see>': the export handle associated with the window</description></item>
        /// <item><description><see cref="CSDL.Props.WindowWaylandXdgPopupPointer">WindowWaylandXdgPopupPointer</see>: the xdg_popup role associated with the window</description></item>
        /// <item><description><see cref="CSDL.Props.WindowWaylandXdgPositionerPointer">WindowWaylandXdgPositionerPointer</see>: the xdg_positioner associated with the window, in popup mode</description></item>
        /// </list>
        /// <para>On X11:</para>
        /// <list type="bullet">
