        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UpdateWindowSurface">SDL_UpdateWindowSurface</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Video.Window.GetWindowSurface">GetWindowSurface</see></seealso>
        /// <seealso><see cref="CSDL.Video.Window.UpdateWindowSurfaceRects">UpdateWindowSurfaceRects</see></seealso>
        public static extern void UpdateWindowSurface();

        /// <summary>
        /// <para>Copy areas of the window surface to the screen.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is the function you use to reflect changes to portions of the surface on the screen.</para>
        /// <para>This function is equivalent to the SDL 1.2 API <c>SDL_UpdateRects</c>.</para>
        /// <para>Note that this function will update _at least_ the rectangles specified, but this is only intended as an optimization; in practice, this might update more of the screen (or all of the screen!), depending on what method SDL uses to send pixels to the system.</para>
        /// </remarks>
        /// <param name="window">the window to update.</param>
        /// <param name="rects">an array of <see cref="CSDL.Video.Rect">Rect</see> structures representing areas of the surface to copy, in pixels.</param>
        /// <param name="numrects">the number of rectangles.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UpdateWindowSurfaceRects">SDL_UpdateWindowSurfaceRects</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Video.Window.GetWindowSurface">GetWindowSurface</see></seealso>
        /// <seealso><see cref="CSDL.Video.Window.UpdateWindowSurface">UpdateWindowSurface</see></seealso>
        public static extern void UpdateWindowSurfaceRects();

        /// <summary>
        /// <para>Return whether the window has a surface associated with it.</para>
        /// </summary>
        /// <param name="window">the window to query.</param>
        /// <returns>
        /// <para>(bool) Returns true if there is a surface associated with the window, or false otherwise.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WindowHasSurface">SDL_WindowHasSurface</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Video.Window.GetWindowSurface">GetWindowSurface</see></seealso>
        public static extern void WindowHasSurface();
    }
